//! Every configuration key in `config.toml`, as constants: one [`KeyDef`] per key and
//! the [`KEYS`] table. Generated by `scripts/gen-config.py`; do not edit. Change
//! `config.toml` and run `just gen-config`; `just lint-config` fails while this file
//! is stale (ADR 0020).

use super::{KeyDef, Kind};

/// `dir`, path: The driver directory: where the driver creates its counters file, command ring, broadcast buffer and log buffers, and where clients and doctor find it (spec/client-protocol.md, The driver directory). A relative path is relative to the working directory of the process that reads it.
pub const DIR: KeyDef = KeyDef {
    name: "dir",
    env: "CAVALRY_DIR",
    flag: Some("--dir"),
    kind: Kind::Path,
    values: &[],
    default: "cavalry-<user> under /dev/shm on Linux when /dev/shm exists, else under the temporary directory",
    term: "driver directory",
    doc: "The driver directory: where the driver creates its counters file, command ring, broadcast buffer and log buffers, and where clients and doctor find it (spec/client-protocol.md, The driver directory). A relative path is relative to the working directory of the process that reads it.",
    why_not_default: "One directory per host and user is right on a laptop and on a cloud VM, and wrong for two drivers on one host, for a container whose /dev/shm is 64 MiB or absent, and for a host whose memory-backed filesystem is mounted elsewhere; the default cannot know which host it is on.",
    doctor: "driver-directory-backing",
    anchor: "docs/reference/config.md#dir",
};

/// `conductor.idle.strategy`, one of backoff, yield, busy-spin: What the conductor's thread does on a duty cycle that found no work: backoff spins, then yields, then sleeps for longer and longer up to 1 ms; yield gives the CPU up on every idle cycle; busy-spin never leaves the CPU. The running driver records its choice in the conductor.idle_strategy counter.
pub const CONDUCTOR_IDLE_STRATEGY: KeyDef = KeyDef {
    name: "conductor.idle.strategy",
    env: "CAVALRY_CONDUCTOR_IDLE_STRATEGY",
    flag: None,
    kind: Kind::Enum,
    values: &["backoff", "yield", "busy-spin"],
    default: "backoff",
    term: "idle strategy",
    doc: "What the conductor's thread does on a duty cycle that found no work: backoff spins, then yields, then sleeps for longer and longer up to 1 ms; yield gives the CPU up on every idle cycle; busy-spin never leaves the CPU. The running driver records its choice in the conductor.idle_strategy counter.",
    why_not_default: "Backoff is right on a laptop and on a cloud VM, where a spinning conductor would take a core from the clients; busy-spin is right on an isolated core, where backoff's sleep of up to 1 ms delays the limit a publisher waits on; the driver cannot tell from inside which core it was given.",
    doctor: "conductor-idle-strategy",
    anchor: "docs/reference/config.md#conductoridlestrategy",
};

/// Every key of `config.toml`, in the file's order.
pub const KEYS: &[&KeyDef] = &[&DIR, &CONDUCTOR_IDLE_STRATEGY];
